    "rättSvar": 2.125,
    "tolerans": 0.03825,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Negativ hastighet minskar förflyttningen men bidrar fortfarande positivt till den tillryggalagda sträckan.</p>",
