    "tolerans": 0.018367,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Jämför uttrycken \\(GM/R^2\\) som en kvot så försvinner \\(G\\).</p>",
