    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Gör om effekten till kW och multiplicera med den totala tiden i timmar.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "kWh"
