    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Använd nyttig effekt \\(\\eta P\\), inte hela märkeffekten.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "min"
