    "tolerans": 0.023143,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>I kortslutningsmodellen återstår i princip bara batteriets inre resistans.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "Ω"
