    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Fältets riktning definieras som kraftens riktning på en positiv testladdning.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "N"
