    "tolerans": 0.0035975991994662213,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>I Coulombs lag står avståndet i kvadrat. Lös ut \\(r\\) med en kvadratrot.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "m"
