    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Samma energimängd lämnar det varma materialet som tas upp av det kalla vattnet.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "°C"
