    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Använd två tydliga punkter på den röda linjen, gärna origo och punkten vid 400 cm³.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "g/cm³",
    "spel": true
